"use strict";
function getNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}
export function calculateVaultExposure(totalAssets, totalIdle) {
  if (totalAssets <= 0) return 0;
  const deployed = totalAssets - totalIdle;
  if (deployed <= 0) return 0;
  const exposure = deployed / totalAssets * 100;
  return Math.max(0, Math.min(100, exposure));
}
export function buildVaultData(morphoVault, tokenPriceUsd, apy) {
  const totalAssetsNumber = getNumber(morphoVault.totalAssetsFormatted);
  const totalIdleNumber = getNumber(morphoVault.totalIdleFormatted);
  const sharePriceNumber = getNumber(morphoVault.sharePriceFormatted);
  const depositsUsd = tokenPriceUsd > 0 ? totalAssetsNumber * tokenPriceUsd : 0;
  const liquidityUsd = tokenPriceUsd > 0 ? totalIdleNumber * tokenPriceUsd : 0;
  return {
    id: morphoVault.address,
    address: morphoVault.address,
    name: morphoVault.name,
    symbol: morphoVault.symbol,
    token: {
      id: morphoVault.asset.address,
      address: morphoVault.asset.address,
      symbol: morphoVault.asset.symbol,
      name: morphoVault.asset.name,
      decimals: morphoVault.asset.decimals
    },
    deposits: totalAssetsNumber,
    depositsUsd,
    liquidity: totalIdleNumber,
    liquidityUsd,
    exposure: calculateVaultExposure(totalAssetsNumber, totalIdleNumber),
    apy,
    sharePrice: sharePriceNumber,
    feePercent: morphoVault.feePercent,
    isVerified: true,
    tokenPriceUsd
  };
}
