"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { useMorphoVaultTransaction } from "hooks/morpho";
import { useCallback, useEffect } from "react";
import { ArrowUpRight, CheckCircle, X } from "react-feather";
import { Button, Flex, SpinningLoader, Text, styled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useEarnContext } from "../ContextProvider";
const CloseIcon = styled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const SummaryCard = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing8",
  width: "100%",
  marginBottom: "$spacing24"
});
const UsdPill = styled(Flex, {
  backgroundColor: "$surface3",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  borderRadius: "$rounded12",
  justifyContent: "center",
  alignItems: "center",
  marginLeft: "$spacing8"
});
const StatusSection = styled(Flex, {
  flexDirection: "column",
  gap: "$spacing16",
  marginBottom: "$spacing24"
});
const StatusRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center"
});
const DoneButton = styled(Button, {
  width: "100%",
  borderRadius: "$rounded20",
  py: "$spacing24",
  marginBottom: "$spacing16"
});
const ProgressRow = styled(Flex, {
  flexDirection: "row",
  width: "100%",
  gap: "$gap8",
  marginBottom: "$spacing12"
});
const ProgressSegment = styled(Flex, {
  height: "4px",
  borderRadius: "$roundedFull",
  flex: 1,
  variants: {
    status: {
      active: { backgroundColor: "$accent1" },
      completed: { backgroundColor: "$greenVibrant" },
      pending: { backgroundColor: "$surface3" },
      error: { backgroundColor: "$red" }
    }
  }
});
const FooterRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const ExplorerLink = styled(Flex, {
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap4",
  cursor: "pointer"
});
const EXPLORER_URL = "https://abscan.org";
function truncateAddress(address) {
  return `${address.slice(0, 6)}...${address.slice(-4)}`;
}
export default function ConfirmModal({ isOpen, onClose, vault }) {
  const colors = useSporeColors();
  const { transactionAmount: amount, transactionType: type, closeTransaction } = useEarnContext();
  const chainId = UniverseChainId.Mainnet;
  const { state, deposit, withdraw, reset } = useMorphoVaultTransaction(chainId);
  const tokenSymbol = vault.token.symbol;
  const isDeposit = type === "deposit";
  const actionLabel = isDeposit ? "Deposit" : "Withdraw";
  const parsedAmount = parseFloat(amount || "0");
  const executeTransaction = useCallback(async () => {
    if (!amount || parsedAmount <= 0) return;
    if (isDeposit) {
      await deposit(vault.address, amount, vault.token.decimals);
    } else {
      await withdraw(vault.address, amount, vault.token.decimals);
    }
  }, [amount, parsedAmount, isDeposit, deposit, withdraw, vault.address, vault.token.decimals]);
  useEffect(() => {
    if (isOpen && state.status === "idle") {
      executeTransaction();
    }
  }, [isOpen, state.status, executeTransaction]);
  useEffect(() => {
    if (!isOpen) {
      reset();
    }
  }, [isOpen, reset]);
  const handleClose = useCallback(() => {
    reset();
    closeTransaction();
    onClose();
  }, [reset, closeTransaction, onClose]);
  useEffect(() => {
    if (state.status === "error") {
      const errorMessage = state.error || "Transaction failed";
      const isCancellation = errorMessage === "Transaction cancelled";
      if (!isCancellation) {
        popupRegistry.addPopup(
          {
            type: PopupType.SimpleMessage,
            content: {
              type: "error",
              title: "Transaction Failed",
              description: errorMessage
            }
          },
          `earn-error-${Date.now()}`
        );
      }
      handleClose();
    }
  }, [state.status, state.error, handleClose]);
  const handleViewOnExplorer = () => {
    const hash = state.txHash || state.approvalTxHash;
    if (hash) {
      window.open(`${EXPLORER_URL}/tx/${hash}`, "_blank");
    }
  };
  const isProcessing = state.status === "approving" || state.status === "executing";
  const isSuccess = state.status === "success";
  const getStepInfo = () => {
    if (state.status === "approving") {
      return { step: 1, text: "Approving token...", address: vault.token.address };
    }
    if (state.status === "executing") {
      return { step: 2, text: `${actionLabel}ing...`, address: vault.address };
    }
    if (state.status === "success") {
      return { step: 3, text: "Transaction complete!", address: null };
    }
    return { step: 0, text: "Preparing...", address: null };
  };
  const stepInfo = getStepInfo();
  return <Modal
    name={"ConfirmModal"}
    isModalOpen={isOpen}
    onClose={handleClose}
    backgroundColor={colors.surface1?.val ?? "#1a1a1a"}
    maxWidth={480}
    padding="$spacing24"
  >
      <ModalHeader>
        <Text variant="heading2" $md={{ variant: "heading3" }} color="$neutral1">
          {isSuccess ? "Success" : "Confirm"}
        </Text>
        <CloseIcon onPress={handleClose}>
          <X size={24} color={colors.neutral2?.val ?? "#888"} />
        </CloseIcon>
      </ModalHeader>

      <SummaryCard>
        <Flex flexDirection="row" alignItems="center" gap="$gap12" mb="$spacing24">
          <PortfolioLogo
    chainId={chainId}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name || ""}
    images={[getTokenLogoUrl(vault.token.address)]}
    size={24}
  />
          <Text variant="heading3" color="$neutral1">
            {vault.name}
          </Text>
        </Flex>

        <Text variant="body2" color="$neutral2" mb="$spacing8">
          {actionLabel}
        </Text>

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Flex flexDirection="row" alignItems="center">
            <Text variant="heading3" color="$neutral1">
              {amount || "0"}
            </Text>
            <Text variant="heading3" color="$neutral2" ml="$spacing4">
              {tokenSymbol}
            </Text>
          </Flex>
          <PortfolioLogo
    chainId={chainId}
    tokenSymbol={vault.token.symbol}
    tokenName={vault.token.name || ""}
    images={[getTokenLogoUrl(vault.token.address)]}
    size={24}
  />
        </Flex>
      </SummaryCard>

      {isProcessing && <StatusSection>
          <StatusRow>
            <Text variant="body2" color="$neutral1">
              {stepInfo.text}
            </Text>
            <SpinningLoader size={20} color={colors.accent1?.val} />
          </StatusRow>

          <ProgressRow>
            <ProgressSegment status={state.status === "approving" ? "active" : "completed"} />
            <ProgressSegment status={state.status === "executing" ? "active" : "pending"} />
          </ProgressRow>

          <Text variant="body3" color="$neutral2">
            {state.status === "approving" ? "Step 1/2 - Approve in wallet" : "Step 2/2 - Confirm in wallet"}
          </Text>
        </StatusSection>}

      {isSuccess && <StatusSection>
          <Flex centered py="$spacing16">
            <CheckCircle size={48} color={colors.statusSuccess?.val ?? "#22c55e"} />
          </Flex>
          <Text variant="body2" color="$neutral1" textAlign="center">
            Your {isDeposit ? "deposit" : "withdrawal"} was successful!
          </Text>
          <DoneButton onPress={handleClose}>Done</DoneButton>
        </StatusSection>}

      {(state.txHash || state.approvalTxHash) && <FooterRow>
          <Flex opacity={1} hoverStyle={{ opacity: 0.75 }} transition="opacity 0.2s ease-in-out">
            <ExplorerLink onPress={handleViewOnExplorer}>
              <Text variant="body3" color="$neutral2">
                View on explorer
              </Text>
              <ArrowUpRight size={14} color={colors.neutral3?.val} />
            </ExplorerLink>
          </Flex>
        </FooterRow>}
    </Modal>;
}
