"use strict";
import { useQuery } from "@tanstack/react-query";
import { usePublicClient } from "wagmi";
import { formatUnits } from "viem";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { MORPHO_VAULTS, MORPHO_VAULT_ABI } from "constants/morpho";
async function fetchVaultData(vaultConfig, publicClient) {
  if (!publicClient) return null;
  try {
    const [totalAssets, totalSupply, fee] = await publicClient.multicall({
      allowFailure: false,
      contracts: [
        {
          address: vaultConfig.address,
          abi: MORPHO_VAULT_ABI,
          functionName: "totalAssets"
        },
        {
          address: vaultConfig.address,
          abi: MORPHO_VAULT_ABI,
          functionName: "totalSupply"
        },
        {
          address: vaultConfig.address,
          abi: MORPHO_VAULT_ABI,
          functionName: "fee"
        }
      ]
    });
    let totalIdle = totalAssets;
    try {
      totalIdle = await publicClient.readContract({
        address: vaultConfig.address,
        abi: MORPHO_VAULT_ABI,
        functionName: "totalIdle"
      });
    } catch (error) {
      console.warn(`totalIdle() unavailable for ${vaultConfig.symbol}, falling back to totalAssets`, error);
    }
    let lastTotalAssets = totalAssets;
    try {
      lastTotalAssets = await publicClient.readContract({
        address: vaultConfig.address,
        abi: MORPHO_VAULT_ABI,
        functionName: "lastTotalAssets"
      });
    } catch (error) {
      console.warn(`lastTotalAssets() unavailable for ${vaultConfig.symbol}, falling back to totalAssets`, error);
    }
    const assetDecimals = vaultConfig.asset.decimals;
    const shareDecimals = 18;
    const sharePrice = totalSupply > 0n ? totalAssets * 10n ** BigInt(shareDecimals) / totalSupply : 10n ** BigInt(assetDecimals);
    return {
      id: vaultConfig.address,
      address: vaultConfig.address,
      name: vaultConfig.name,
      symbol: vaultConfig.symbol,
      asset: vaultConfig.asset,
      totalAssets,
      totalAssetsFormatted: formatUnits(totalAssets, assetDecimals),
      totalSupply,
      totalSupplyFormatted: formatUnits(totalSupply, shareDecimals),
      totalIdle,
      totalIdleFormatted: formatUnits(totalIdle, assetDecimals),
      lastTotalAssets,
      lastTotalAssetsFormatted: formatUnits(lastTotalAssets, assetDecimals),
      sharePrice,
      sharePriceFormatted: formatUnits(sharePrice, assetDecimals),
      feePercent: Number(fee) / 1e16,
      chainId: vaultConfig.chainId
    };
  } catch (error) {
    console.error(`Failed to fetch vault data for ${vaultConfig.symbol}:`, error);
    return null;
  }
}
export function useMorphoVaults(chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-vaults", chainId],
    queryFn: async () => {
      if (!publicClient) return [];
      const vaultConfigs = Object.values(MORPHO_VAULTS).filter((v) => v.chainId === chainId);
      const results = await Promise.all(vaultConfigs.map((config) => fetchVaultData(config, publicClient)));
      return results.filter((v) => v !== null);
    },
    enabled: !!publicClient,
    refetchInterval: 3e4,
    staleTime: 15e3
  });
}
export function useMorphoVault(vaultAddress, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-vault", vaultAddress, chainId],
    queryFn: async () => {
      if (!publicClient) return null;
      const vaultConfig = Object.values(MORPHO_VAULTS).find(
        (v) => v.address.toLowerCase() === vaultAddress.toLowerCase() && v.chainId === chainId
      );
      if (!vaultConfig) {
        console.error(`Vault config not found for address ${vaultAddress}`);
        return null;
      }
      return fetchVaultData(vaultConfig, publicClient);
    },
    enabled: !!publicClient && !!vaultAddress,
    refetchInterval: 3e4,
    staleTime: 15e3
  });
}
