"use strict";
import { useMemo } from "react";
import {
  getTokenUsdPrice,
  useMorphoOraclePrices,
  useMorphoVault,
  useMorphoVaults,
  useMorphoVaultApys,
  useMorphoVaultApy
} from "hooks/morpho";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { buildVaultData } from "../utils";
export function useEarnVaults(chainId = UniverseChainId.Mainnet) {
  const { data: morphoVaults, isLoading: isLoadingVaults, isError } = useMorphoVaults(chainId);
  const { data: prices, isLoading: isLoadingPrices } = useMorphoOraclePrices(chainId);
  const { data: apyMap, isLoading: isLoadingApy } = useMorphoVaultApys(chainId);
  const vaults = useMemo(() => {
    if (!morphoVaults) return [];
    return morphoVaults.map((vault) => {
      const apy = apyMap?.get(vault.address.toLowerCase()) ?? 0;
      return buildVaultData(vault, getTokenUsdPrice(vault.asset.symbol, prices), apy);
    });
  }, [morphoVaults, prices, apyMap]);
  return {
    vaults,
    isLoading: isLoadingVaults || isLoadingPrices || isLoadingApy,
    isError
  };
}
export function useEarnVault(vaultAddress, chainId = UniverseChainId.Mainnet) {
  const { data: morphoVault, isLoading: isLoadingVault, isError } = useMorphoVault(vaultAddress, chainId);
  const { data: prices, isLoading: isLoadingPrices } = useMorphoOraclePrices(chainId);
  const { data: apy, isLoading: isLoadingApy } = useMorphoVaultApy(vaultAddress, chainId);
  const vault = useMemo(() => {
    if (!morphoVault) return null;
    return buildVaultData(morphoVault, getTokenUsdPrice(morphoVault.asset.symbol, prices), apy ?? 0);
  }, [morphoVault, prices, apy]);
  return {
    vault,
    isLoading: isLoadingVault || isLoadingPrices || isLoadingApy,
    isError
  };
}
