"use strict";
import { useState, useCallback, useMemo, useRef } from "react";
import { usePublicClient, useWriteContract, useConnectorClient } from "wagmi";
import { parseUnits } from "viem";
import { useAccount } from "hooks/useAccount";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useEip5792Support } from "uniswap/src/features/transactions/swap/contexts/hooks/useEip5792Support";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { MORPHO_VAULT_ABI, ERC20_ABI, MORPHO_VAULTS } from "constants/morpho";
import { MorphoBatchedTransactionService } from "./MorphoBatchedTransactionService";
function parseTransactionError(error) {
  if (!error) return "Transaction failed";
  const errorMessage = error instanceof Error ? error.message : String(error);
  const lowerMessage = errorMessage.toLowerCase();
  if (lowerMessage.includes("user rejected") || lowerMessage.includes("user denied") || lowerMessage.includes("rejected the request") || lowerMessage.includes("user cancelled") || lowerMessage.includes("user canceled") || lowerMessage.includes("action_rejected")) {
    return "Transaction cancelled";
  }
  if (lowerMessage.includes("insufficient funds") || lowerMessage.includes("insufficient balance")) {
    return "Insufficient funds for gas";
  }
  if (lowerMessage.includes("execution reverted")) {
    return "Transaction would fail - please check your inputs";
  }
  if (lowerMessage.includes("network") || lowerMessage.includes("timeout") || lowerMessage.includes("disconnected")) {
    return "Network error - please try again";
  }
  if (lowerMessage.includes("nonce")) {
    return "Transaction conflict - please try again";
  }
  if (errorMessage.length > 100) {
    return "Transaction failed - please try again";
  }
  return errorMessage;
}
export function useMorphoVaultTransaction(chainId = UniverseChainId.Mainnet) {
  const { address } = useAccount();
  const publicClient = usePublicClient({ chainId });
  const { writeContractAsync } = useWriteContract();
  const { data: client } = useConnectorClient();
  const { supported: supportsEip5792 } = useEip5792Support(chainId);
  const batchedService = useMemo(() => new MorphoBatchedTransactionService(), []);
  const isExecutingRef = useRef(false);
  const [state, setState] = useState({
    status: "idle",
    error: null,
    txHash: null,
    approvalTxHash: null
  });
  const reset = useCallback(() => {
    isExecutingRef.current = false;
    setState({
      status: "idle",
      error: null,
      txHash: null,
      approvalTxHash: null
    });
  }, []);
  const deposit = useCallback(
    async (vaultAddress, amount, decimals) => {
      if (isExecutingRef.current) {
        console.log("[Morpho] Deposit already in progress, ignoring duplicate call");
        return;
      }
      if (!publicClient || !address) {
        setState((s) => ({ ...s, status: "error", error: "Wallet not connected" }));
        return;
      }
      const vaultConfig = Object.values(MORPHO_VAULTS).find(
        (v) => v.address.toLowerCase() === vaultAddress.toLowerCase()
      );
      if (!vaultConfig) {
        setState((s) => ({ ...s, status: "error", error: "Vault not found" }));
        return;
      }
      isExecutingRef.current = true;
      try {
        const amountBn = parseUnits(amount, decimals);
        const allowance = await publicClient.readContract({
          address: vaultConfig.asset.address,
          abi: ERC20_ABI,
          functionName: "allowance",
          args: [address, vaultAddress]
        });
        const needsApproval = allowance < amountBn;
        const canUseBatching = needsApproval && supportsEip5792 && client;
        let txHash;
        if (canUseBatching) {
          console.log("\u2705 [EIP-5792] Using atomic batch for approve + deposit");
          const batchedTxs = batchedService.buildBatchedVaultDeposit({
            assetAddress: vaultConfig.asset.address,
            vaultAddress,
            amount: amountBn,
            account: address,
            chainId
          });
          const calls = batchedTxs.map(({ to, data, value }) => ({ to, data, value }));
          const chainHex = `0x${chainId.toString(16)}`;
          setState((s) => ({ ...s, status: "executing" }));
          const result = await client.request({
            method: "wallet_sendCalls",
            params: [
              {
                version: "2.0.0",
                calls,
                from: address,
                chainId: chainHex,
                atomicRequired: true
              }
            ]
          });
          txHash = result.id;
          console.log("\u2705 [EIP-5792] Batched vault deposit submitted:", txHash);
          setState((s) => ({ ...s, txHash }));
          popupRegistry.addPopup({ type: PopupType.Transaction, hash: txHash }, txHash);
          setState((s) => ({ ...s, status: "success" }));
        } else {
          if (needsApproval) {
            setState((s) => ({ ...s, status: "approving" }));
            const approveTxHash = await writeContractAsync({
              address: vaultConfig.asset.address,
              abi: ERC20_ABI,
              functionName: "approve",
              args: [vaultAddress, amountBn]
            });
            setState((s) => ({ ...s, approvalTxHash: approveTxHash }));
            popupRegistry.addPopup({ type: PopupType.Transaction, hash: approveTxHash }, approveTxHash);
            await publicClient.waitForTransactionReceipt({ hash: approveTxHash });
          }
          setState((s) => ({ ...s, status: "executing" }));
          txHash = await writeContractAsync({
            address: vaultAddress,
            abi: MORPHO_VAULT_ABI,
            functionName: "deposit",
            args: [amountBn, address]
          });
          setState((s) => ({ ...s, txHash }));
          popupRegistry.addPopup({ type: PopupType.Transaction, hash: txHash }, txHash);
          await publicClient.waitForTransactionReceipt({ hash: txHash });
          setState((s) => ({ ...s, status: "success" }));
        }
      } catch (error) {
        console.error("Deposit failed:", error);
        setState((s) => ({
          ...s,
          status: "error",
          error: parseTransactionError(error)
        }));
      } finally {
        isExecutingRef.current = false;
      }
    },
    [publicClient, address, chainId, supportsEip5792, client, batchedService, writeContractAsync]
  );
  const withdraw = useCallback(
    async (vaultAddress, amount, decimals) => {
      if (isExecutingRef.current) {
        console.log("[Morpho] Withdraw already in progress, ignoring duplicate call");
        return;
      }
      if (!publicClient || !address) {
        setState((s) => ({ ...s, status: "error", error: "Wallet not connected" }));
        return;
      }
      isExecutingRef.current = true;
      try {
        setState((s) => ({ ...s, status: "executing" }));
        const amountBn = parseUnits(amount, decimals);
        const shares = await publicClient.readContract({
          address: vaultAddress,
          abi: MORPHO_VAULT_ABI,
          functionName: "convertToShares",
          args: [amountBn]
        });
        let txHash;
        if (supportsEip5792 && client) {
          console.log("\u2705 [EIP-5792] Using wallet_sendCalls for withdraw");
          const batchedTxs = batchedService.buildVaultWithdraw({
            vaultAddress,
            shares,
            account: address,
            chainId
          });
          const calls = batchedTxs.map(({ to, data, value }) => ({ to, data, value }));
          const chainHex = `0x${chainId.toString(16)}`;
          const result = await client.request({
            method: "wallet_sendCalls",
            params: [
              {
                version: "2.0.0",
                calls,
                from: address,
                chainId: chainHex,
                atomicRequired: true
              }
            ]
          });
          txHash = result.id;
          console.log("\u2705 [EIP-5792] Withdraw submitted:", txHash);
          setState((s) => ({ ...s, txHash }));
          popupRegistry.addPopup({ type: PopupType.Transaction, hash: txHash }, txHash);
          setState((s) => ({ ...s, status: "success" }));
        } else {
          txHash = await writeContractAsync({
            address: vaultAddress,
            abi: MORPHO_VAULT_ABI,
            functionName: "redeem",
            args: [shares, address, address]
          });
          setState((s) => ({ ...s, txHash }));
          popupRegistry.addPopup({ type: PopupType.Transaction, hash: txHash }, txHash);
          await publicClient.waitForTransactionReceipt({ hash: txHash });
          setState((s) => ({ ...s, status: "success" }));
        }
      } catch (error) {
        console.error("Withdraw failed:", error);
        setState((s) => ({
          ...s,
          status: "error",
          error: parseTransactionError(error)
        }));
      } finally {
        isExecutingRef.current = false;
      }
    },
    [publicClient, address, chainId, supportsEip5792, client, batchedService, writeContractAsync]
  );
  return {
    state,
    deposit,
    withdraw,
    reset
  };
}
