"use strict";
import { useQuery } from "@tanstack/react-query";
import { usePublicClient } from "wagmi";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { MORPHO_ADDRESS, MORPHO_ABI, MORPHO_VAULTS, MORPHO_MARKETS } from "constants/morpho";
const VAULT_TO_MARKETS = {
  // abxUSDC vault allocates to PENGU/USDC market
  [MORPHO_VAULTS.abxUSDC.address.toLowerCase()]: [MORPHO_MARKETS.PENGU_USDC.id],
  // abxWETH vault allocates to USDC/WETH market (borrow WETH against USDC)
  [MORPHO_VAULTS.abxWETH.address.toLowerCase()]: [MORPHO_MARKETS.USDC_WETH.id]
};
function calculateBorrowRate(utilization) {
  const utilizationPercent = Number(utilization) / 1e18;
  const baseBorrowRate = 0.02;
  const maxRate = 0.5;
  const optimalUtilization = 0.9;
  if (utilizationPercent <= optimalUtilization) {
    return baseBorrowRate + utilizationPercent / optimalUtilization * 0.08;
  } else {
    const excessUtilization = (utilizationPercent - optimalUtilization) / (1 - optimalUtilization);
    return baseBorrowRate + 0.08 + excessUtilization * (maxRate - baseBorrowRate - 0.08);
  }
}
async function fetchMarketSupplyRate(marketId, publicClient) {
  if (!publicClient) return 0;
  try {
    const marketData = await publicClient.readContract({
      address: MORPHO_ADDRESS,
      abi: MORPHO_ABI,
      functionName: "market",
      args: [marketId]
    });
    const [totalSupplyAssets, , totalBorrowAssets] = marketData;
    if (totalSupplyAssets === 0n) return 0;
    const utilizationRate = Number(totalBorrowAssets * 10000n / totalSupplyAssets) / 100;
    const utilization = totalBorrowAssets * BigInt(1e18) / totalSupplyAssets;
    const borrowRate = calculateBorrowRate(utilization) * 100;
    const supplyRate = borrowRate * (utilizationRate / 100);
    return supplyRate;
  } catch (error) {
    console.error(`Failed to fetch market supply rate for ${marketId}:`, error);
    return 0;
  }
}
export function useMorphoVaultApys(chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-vault-apys", chainId],
    queryFn: async () => {
      if (!publicClient) return /* @__PURE__ */ new Map();
      const apyMap = /* @__PURE__ */ new Map();
      const vaultConfigs = Object.values(MORPHO_VAULTS).filter((v) => v.chainId === chainId);
      for (const vault of vaultConfigs) {
        const marketIds = VAULT_TO_MARKETS[vault.address.toLowerCase()];
        if (!marketIds || marketIds.length === 0) {
          apyMap.set(vault.address.toLowerCase(), 0);
          continue;
        }
        const rates = await Promise.all(
          marketIds.map((id) => fetchMarketSupplyRate(id, publicClient))
        );
        const avgRate = rates.reduce((sum, rate) => sum + rate, 0) / rates.length;
        apyMap.set(vault.address.toLowerCase(), avgRate);
      }
      return apyMap;
    },
    enabled: !!publicClient,
    refetchInterval: 6e4,
    staleTime: 3e4
  });
}
export function useMorphoVaultApy(vaultAddress, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-vault-apy", vaultAddress, chainId],
    queryFn: async () => {
      if (!publicClient || !vaultAddress) return 0;
      const marketIds = VAULT_TO_MARKETS[vaultAddress.toLowerCase()];
      if (!marketIds || marketIds.length === 0) return 0;
      const rates = await Promise.all(
        marketIds.map((id) => fetchMarketSupplyRate(id, publicClient))
      );
      return rates.reduce((sum, rate) => sum + rate, 0) / rates.length;
    },
    enabled: !!publicClient && !!vaultAddress,
    refetchInterval: 6e4,
    staleTime: 3e4
  });
}
