"use strict";
import { useQuery } from "@tanstack/react-query";
import { usePublicClient } from "wagmi";
import { formatUnits } from "viem";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { MORPHO_MARKETS, MORPHO_ORACLE_ABI, MORPHO_TOKENS } from "constants/morpho";
function convertOraclePriceToNumber(oraclePrice, collateralDecimals, loanDecimals) {
  const exponent = 36 - collateralDecimals + loanDecimals;
  return Number(formatUnits(oraclePrice, exponent));
}
export function useMorphoOraclePrices(chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-oracle-prices", chainId],
    queryFn: async () => {
      if (!publicClient) {
        return { WETH: 0, USDC: 1, PENGU: 0 };
      }
      const prices = {
        WETH: 0,
        USDC: 1,
        PENGU: 0
      };
      try {
        const wethUsdcOracle = MORPHO_MARKETS.WETH_USDC.oracle;
        const wethUsdcPrice = await publicClient.readContract({
          address: wethUsdcOracle,
          abi: MORPHO_ORACLE_ABI,
          functionName: "price"
        });
        prices.WETH = convertOraclePriceToNumber(
          wethUsdcPrice,
          MORPHO_TOKENS.WETH.decimals,
          MORPHO_TOKENS.USDC.decimals
        );
      } catch (e) {
        console.warn("Failed to fetch WETH/USDC oracle price:", e);
      }
      try {
        const penguUsdcOracle = MORPHO_MARKETS.PENGU_USDC.oracle;
        const penguUsdcPrice = await publicClient.readContract({
          address: penguUsdcOracle,
          abi: MORPHO_ORACLE_ABI,
          functionName: "price"
        });
        prices.PENGU = convertOraclePriceToNumber(
          penguUsdcPrice,
          MORPHO_TOKENS.PENGU.decimals,
          MORPHO_TOKENS.USDC.decimals
        );
      } catch (e) {
        console.warn("Failed to fetch PENGU/USDC oracle price:", e);
      }
      return prices;
    },
    enabled: !!publicClient,
    refetchInterval: 3e4,
    staleTime: 15e3
  });
}
export function getTokenUsdPrice(symbol, prices) {
  if (!prices) return 0;
  switch (symbol.toUpperCase()) {
    case "WETH":
    case "ETH":
      return prices.WETH;
    case "USDC":
      return prices.USDC;
    case "PENGU":
      return prices.PENGU;
    default:
      return 0;
  }
}
export function useTokenUsdValue(amount, tokenSymbol, chainId = UniverseChainId.Mainnet) {
  const { data: prices, isLoading } = useMorphoOraclePrices(chainId);
  const numAmount = typeof amount === "string" ? parseFloat(amount) || 0 : amount;
  const price = getTokenUsdPrice(tokenSymbol, prices);
  return {
    usdValue: numAmount * price,
    isLoading
  };
}
